select * from user_events;


-- =================================== --
--  SALES FUNNEL ANALYSIS  --
-- =================================== --


--1. INITIAL EXPLORATION  --

-- Occurences of each event_type
select event_type, count(*) as occurences
from user_events
group by event_type
order by count(*) desc;

-- traffic generated by each source
select traffic_source, count(*) as occurences
from user_events
group by traffic_source
order by count(*) desc;

-- FUNNEL AND CONVERSION ANALYSIS --

-- Define sales funnel with different stages
with sales_funnel as(
select 
count(distinct case when event_type='page_view' then user_id end) as stage1_view,
count(distinct case when event_type='add_to_cart' then user_id end) as stage2_cart,
count(distinct case when event_type='checkout_start' then user_id end) as stage3_checkout,
count(distinct case when event_type='payment_info' then user_id end) as stage4_payment,
count(distinct case when event_type='purchase' then user_id end) as stage5_purchase
from user_events
)
select * 
from sales_funnel;


--calculate the conversion rate by each stage
with cte as(
select 
count(distinct case when event_type='page_view' then user_id end) as stage1_view,
count(distinct case when event_type='add_to_cart' then user_id end) as stage2_cart,
count(distinct case when event_type='checkout_start' then user_id end) as stage3_checkout,
count(distinct case when event_type='payment_info' then user_id end) as stage4_payment,
count(distinct case when event_type='purchase' then user_id end) as stage5_purchase
from user_events
)
select 
stage1_view, 
stage2_cart, 
round((stage2_cart*100/stage1_view),2) as view_to_cart_rate,
stage3_checkout, 
round((stage3_checkout*100/stage2_cart),2) as cart_to_checkout_rate,
stage4_payment,
round((stage4_payment*100/stage3_checkout),2) as checkout_to_payment_rate,
stage5_purchase, 
round((stage5_purchase*100/stage4_payment),2) as payment_to_purchase_rate,
round((stage5_purchase*100/stage1_view),2) as overall_conversion_rate
from cte;

-- TRAFFIC SOURCE ANALYSIS --

--sales funnel by each traffic source
with conversion_rate as (
select 
traffic_source, 
count(distinct case when event_type='page_view' then user_id end) as viewer,
count(distinct case when event_type='add_to_cart' then user_id end) as cart,
count(distinct case when event_type='checkout_start' then user_id end) as checkout,
count(distinct case when event_type='payment_info' then user_id end) as payment,
count(distinct case when event_type='purchase' then user_id end) as purchase
from user_events
group by traffic_source
)
select 
traffic_source, 
viewer, 
cart, 
purchase,
cart *100/viewer as cart_conversion,
purchase *100/cart as purchase_conversion,
purchase *100/ viewer as overall_conversion
from conversion_rate
order by purchase desc;

-- TIME AND DROP-OFF ANALYSIS --

--time to conversion analysis
with user_journey as(
select user_id,
	min(case when event_type='page_view' then event_date end) as view_time,
	min(case when event_type='add_to_cart' then event_date end) as cart_time,
	min(case when event_type='purchase' then event_date end) as purchase_time
from user_events
group by user_id
having min(case when event_type='purchase' then event_date end) is not null
)
	select 
	count(*) as converted_users, 
	avg(datediff(minute, view_time, cart_time)) as viewtocart_avg, 
	avg(datediff(minute, cart_time, purchase_time)) as carttopurchase_avg,
	avg(datediff(minute, view_time, purchase_time)) as overall_avgtime
	from user_journey;



--calculate the drop off rate by each stage
with drop_off as(
select 
count(distinct case when event_type='page_view' then user_id end) as viewer,
count(distinct case when event_type='add_to_cart' then user_id end) as cart,
count(distinct case when event_type='checkout_start' then user_id end) as checkout,
count(distinct case when event_type='payment_info' then user_id end) as payment,
count(distinct case when event_type='purchase' then user_id end) as purchase
from user_events
)
select viewer, cart,viewer-cart as viewer_cart_drop, 
(viewer-cart)*100/viewer as viewer_drop_rate,
purchase,viewer-purchase as viewer_purchase_drop,
(viewer-purchase)*100/viewer  as overall_drop_rate
from drop_off;

--drop offs by each traffic source
with conversion_rate as (
select 
traffic_source, 
count(distinct case when event_type='page_view' then user_id end) as viewer,
count(distinct case when event_type='add_to_cart' then user_id end) as cart,
count(distinct case when event_type='checkout_start' then user_id end) as checkout,
count(distinct case when event_type='payment_info' then user_id end) as payment,
count(distinct case when event_type='purchase' then user_id end) as purchase
from user_events
group by traffic_source
)
select 
traffic_source, 
viewer, 
cart, 
viewer-cart as viewer_cart_drop, 
(viewer-cart)*100/viewer as viewer_drop_rate,payment,
payment-purchase as payment_purchase_drop,
purchase,viewer-purchase as viewer_purchase_drop,
(viewer-purchase)*100/viewer  as overall_drop_rate
from conversion_rate;


-- ===========================
-- RECOMMENDATIONS
-- ===========================

-- 1. Email generated the highest overall conversion rate (33%), while social media
-- had the highest drop-off rate. The business could explore opportunities to scale
-- effective email campaigns while reviewing the quality and targeting of social media traffic.

-- 2. Approximately 68% of users dropped off between the page view and add-to-cart stages.
-- The business should investigate potential causes, such as product presentation,
-- website experience, pricing, or other barriers that may prevent users from adding products to their carts.

-- 3. Converted users took an average of 24 minutes to complete a purchase.
-- Further analysis could help determine whether this journey length represents a potential
-- opportunity to simplify the purchase process.
